import re, sys
try:
    import yaml
except ImportError:
    print("NO YAML MODULE")
    sys.exit(1)

with open('governance/check-registry.yaml') as f:
    data = yaml.safe_load(f)

import os
missing = []
seen = []
def check_cmd(entry, where):
    cmd = entry.get('cmd')
    if not cmd:
        return
    # first element is interpreter (python3/node) or script itself
    for tok in cmd:
        if tok.endswith('.py') or tok.endswith('.js') or tok.endswith('.sh'):
            seen.append((entry.get('id'), tok, where))
            if not os.path.exists(tok):
                missing.append((entry.get('id'), tok, where))

for c in data.get('checks', []):
    check_cmd(c, 'checks')
for c in data.get('quarantine', []):
    check_cmd(c, 'quarantine')

print("=== ALL SCRIPT PATHS REFERENCED ===")
for s in seen:
    print(s)
print()
print("=== MISSING PATHS ===")
for m in missing:
    print(m)
